({open, onOpenChange, projectId, memberId, mode = "create"}: CredentialProps) => {
    const [createdCredential, setCreatedCredential] = useState<any>(null);
    const [copied, setCopied] = useState(false);
    const createCredential = useCreateCredential();
    const updateCredential = useUpdateCredential();
    const { data: existingCredential, isLoading: isLoadingCredential } = useGetMemberCredential(projectId, memberId);

    const form = useForm<z.output<typeof createCredentialsSchema>>({
        resolver: zodResolver(createCredentialsSchema),
        defaultValues: {
            name: "",
            api_keys: {
                token: "",
                owner: "",
                repo: "",
            },
            api_limitations: {}
        },
    });

    useEffect(() => {
        if (mode === "edit" && existingCredential && open) { // loading existing credential data
            form.reset({
                name: existingCredential.name || "",
                api_keys: {
                    token: "",
                    owner: existingCredential.api_keys?.owner || "",
                    repo: existingCredential.api_keys?.repo || "",
                },
                api_limitations: existingCredential.api_limitations || {}
            });
        } else if (mode === "create" && open) {
            form.reset({
                name: "",
                api_keys: {
                    token: "",
                    owner: "",
                    repo: "",
                },
                api_limitations: {}
            });
        }
    }, [mode, existingCredential, open, form]);

    const onSubmit = (values: z.infer<typeof createCredentialsSchema>) => {
        if (mode === "edit" && existingCredential?.id) {
            updateCredential.mutate(
                { projectId, memberId, credentialId: existingCredential.id, ...values },
                {
                    onSuccess: () => {
                        toast.success("Credential updated successfully");
                        handleClose();
                    }
                }
            );
        } else {
            createCredential.mutate(
                { projectId, memberId, ...values },
                {
                    onSuccess: (data) => {
                        if (typeof window !== "undefined" && data.initialBackfill) { // checking if using sessionStorage and window is possible, since they only exist in the browser (might need to change after switching to desktop version)
                            // if initialBackfill exists it means credential creation also did an initial commit fetch
                            const backfillNotice = {
                                projectId,
                                memberId,
                                fetchedFromGithub: data.initialBackfill.fetchedFromGithub,
                            };

                            sessionStorage.setItem(
                                "credentialBackfillNotice",
                                JSON.stringify(backfillNotice)
                            );

                            window.dispatchEvent( // in page event telling that the new backfill notice is ready
                                new CustomEvent("credential-backfill-notice", { detail: backfillNotice })
                            );
                        }
                        setCreatedCredential(data); // includes credential + initialBackfill summary
                        // onOpenChange(false); moved these to handleOpenChange
                        // form.reset();
                    }
                }
            );
        }
    };

    const handleOpenChange = (newOpen: boolean) => {
        if (!newOpen) { // dialog closes
            setCreatedCredential(null);
            form.reset();
        }
        onOpenChange(newOpen);
    };

    const handleClose = () => {
        setCreatedCredential(null);
        form.reset();
        onOpenChange(false);
    };

    const handleCopySecret = () => {
        if (!createdCredential) return;
        const secret = createdCredential.data?.api_keys?.webhookSecret;
        if (secret) {
