export function CommitEventDetails({ payload, repository }: { payload: any; repository: string }) {
    const commitData = payload.commit;
    const sha = payload.sha;
    const message = commitData?.message || payload?.message || "No message";
    const dateValue = commitData?.author?.date || payload?.author_date || payload?.timestamp;
    const branch = payload?.branch || "Unknown";
    const pusher = payload?.pusher || commitData?.author?.name || payload?.author_name || "Unknown";
    const senderLogin =
        payload?.sender_login ||
        payload?.sender?.login ||
        payload?.author?.login ||
        payload?.committer?.login ||
        commitData?.author?.name ||
        payload?.author_name ||
        "Unknown";
    const isWebFlowPush = String(pusher).toLowerCase() === "web-flow";

    const parentSha = payload.parents?.[0]?.sha;
    const compareUrl = parentSha
        ? `https://github.com/${repository}/compare/${parentSha}...${sha}`
        : (payload.compare || payload.html_url || "#");

    const fileChanges = payload.files || [];
    const addedFromFiles = fileChanges.filter((file: any) => file.status === "added").length;
    const modifiedFromFiles = fileChanges.filter((file: any) => file.status === "modified").length;
    const removedFromFiles = fileChanges.filter((file: any) => file.status === "removed").length;

    const addedCount = (payload.added || []).length || addedFromFiles;
    const modifiedCount = (payload.modified || []).length || modifiedFromFiles;
    const removedCount = (payload.removed || []).length || removedFromFiles;

    const timeLabel = dateValue
        ? new Date(dateValue).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
        : "Unknown time";

    return (
        <div className="p-6 space-y-4">
            <div className="grid grid-cols-3 gap-4 text-sm mb-4 p-3 bg-muted/50 rounded-lg">
                <div><span className="font-medium">Branch:</span> {branch}</div>
                <div>
                    <span className="font-medium">Pusher:</span> {isWebFlowPush ? "web-flow (GitHub web UI)" : pusher}
                    {isWebFlowPush && (
                        <div className="text-xs text-muted-foreground mt-1">
                            Action performed in GitHub browser by contributor: {senderLogin}
                        </div>
                    )}
                </div>
                <div className="text-right">
                    <a href={compareUrl} target="_blank" rel="noopener noreferrer" className="text-blue-500 hover:text-blue-600 font-medium flex items-center justify-end gap-1 text-sm">
                        View Compare <FileText className="w-3 h-3" />
                    </a>
                </div>
            </div>

            <div className="p-4 bg-muted/30 rounded-lg">
                <div className="text-sm font-semibold mb-3 flex items-center gap-2">
                    <GitCommit className="w-4 h-4" />
                    1 Commit
                </div>

                <div className="grid grid-cols-1 gap-3">
                    <CommitCard
                        shortId={String(sha)}
                        message={message}
                        timeLabel={timeLabel}
                        addedCount={addedCount}
                        modifiedCount={modifiedCount}
                        removedCount={removedCount}
                    />
                </div>
            </div>
        </div>
    );
}

export function MemberEventSelector({ projectId }: MemberSelectorProps) {
    const { data: members, isLoading, isError } = useGetProjectMembers(projectId);
    const [selectedMemberId, setSelectedMemberId] = useState<string | null>(null);

    useEffect(() => {
        if (!members || members.length === 0) {
            setSelectedMemberId(null);
            return;
        }

        setSelectedMemberId((current) => {
            if (current && members.some((member: any) => member.id === current)) {
                return current;
            }
            return members[0].id;
        });
    }, [members]);

    if (isLoading) {
        return <div>Loading members...</div>;
    }
    if (isError) {
        return <div className="text-red-500">Could not load members</div>;
    }
    if (!members || members.length === 0) {
        return <div>No members yet</div>;
    }

    return (
        <div className="space-y-4">
            <Select value={selectedMemberId || ""} onValueChange={setSelectedMemberId}>
                <SelectTrigger className="w-50">
                    <SelectValue placeholder="Select a member" />
                </SelectTrigger>
                <SelectContent>
                    {members.map((member) => (
                        <SelectItem key={member.id} value={member.id}>
                            {member.expand?.user?.name || member.expand?.user?.email || member.id}
                        </SelectItem>
                    ))}
                </SelectContent>
            </Select>

        {selectedMemberId && <WebhookEventsList projectId={projectId} memberId={selectedMemberId} />}
        </div>
    );
}

export function WebhookEventsList({ projectId, memberId }: Props) { 
    const queryClient = useQueryClient();
    const { data: events, isLoading, isError } = useGetMemberWebhookEvents(projectId, memberId);
    const safeEvents = events ?? [];
    const [expandedEventIds, setExpandedEventIds] = useState<string[]>([]);
    const [isRefreshingCommits, setIsRefreshingCommits] = useState(false);
    const [syncSummary, setSyncSummary] = useState<string[]>([]);

    useEffect(() => { // for retrieving the initial 'create credential' commits backfill notice
        if (typeof window === "undefined") {
            return;
        }

        const applyBackfillNotice = () => {
            const rawNotice = sessionStorage.getItem("credentialBackfillNotice");
            if (!rawNotice) {
                return;
            }

            try {
                const parsed = JSON.parse(rawNotice) as {
                    projectId?: string;
                    memberId?: string;
                    fetchedFromGithub?: number;
                };

                if (parsed.projectId === projectId && parsed.memberId === memberId) {
                    const fetched = parsed.fetchedFromGithub ?? 0;
                    setSyncSummary([
                        `Initial 'create commit' backfill action: fetched ${fetched} commits`,
                    ]);
                    sessionStorage.removeItem("credentialBackfillNotice");
                }
            } catch {
                sessionStorage.removeItem("credentialBackfillNotice");
            }
        };

        const onBackfillNotice = () => {
            applyBackfillNotice();
        };

        applyBackfillNotice();
        window.addEventListener("credential-backfill-notice", onBackfillNotice);

        return () => {
            window.removeEventListener("credential-backfill-notice", onBackfillNotice);
        };
    }, [projectId, memberId]);

    const getEventGithubTimestamp = (event: any) => {
        if (event?.event_type === "commit") {
            return Date.parse(event?.payload?.commit?.author?.date || event?.payload?.author?.date || event?.payload?.timestamp || "") || 0;
        }

        return Date.parse(event?.created || "") || 0;
    };

    const sortedEvents = [...safeEvents].sort((a, b) => getEventGithubTimestamp(b) - getEventGithubTimestamp(a));

    const expandEventBehaviour = (eventId: string) => {
        setExpandedEventIds(prev => 
            prev.includes(eventId)
                ? prev.filter(id => id !== eventId) // remove if expanded
                : [...prev, eventId] // add if collapsed
        );
    };

    const getEventDetailsClassName = (eventId: string) =>
        cn(
            "overflow-hidden transition-all duration-300 ease-in-out",
            expandedEventIds.includes(eventId)
                ? "max-h-96 opacity-100 pt-0"
                : "max-h-0 opacity-0 -mt-4"
        );

    const refreshCommits = useCallback(async (options?: { silent?: boolean; auto?: boolean }) => {
        if (safeEvents.length === 0) {
            return;
        }

        const repositories = Array.from(
            new Set(safeEvents.map((event: any) => event.repository).filter(Boolean))
        );

        if (repositories.length === 0) {
            if (!options?.silent) {
                toast.error("No repository found to refresh commits");
            }
            return;
        }

        setIsRefreshingCommits(true);
        try {
            const nextSyncSummary: string[] = [];

            for (const repo of repositories) {
                const result = await fetchGetCommits({ projectId, memberId, repo });

                const backfill = result.backfill as {
                    fetchedFromGithub?: number;
                    skippedExisting?: number;
                } | undefined;
                const fetched = backfill?.fetchedFromGithub ?? 0;
                const skippedExisting = backfill?.skippedExisting ?? 0;
                nextSyncSummary.push(
                    `${options?.auto ? "Auto" : "Current 'update commit'"} backfill action: fetched ${fetched} commits (skipped existing commits: ${skippedExisting})`
                );
            }

            setSyncSummary(nextSyncSummary);
            await queryClient.invalidateQueries({
                queryKey: ["projects", projectId, "members", memberId, "commits"],
            });
            if (!options?.silent) {
                toast.success("Commits refreshed");
            }
        } catch (error) {
            if (!options?.silent) {
                toast.error(error instanceof Error ? error.message : "Failed to refresh commits");
            }
        } finally {
            setIsRefreshingCommits(false);
        }
    }, [memberId, projectId, queryClient, safeEvents]);

    useEffect(() => {
        if (safeEvents.length === 0) {
            return;
        }

        const intervalId = window.setInterval(() => {
            if (isRefreshingCommits) {
                return;
            }

            void refreshCommits({ silent: true, auto: true });
        }, 15000);

        return () => {
            window.clearInterval(intervalId);
        };
    }, [isRefreshingCommits, refreshCommits, safeEvents]);

    if (isLoading) {
        return <div>Loading events...</div>;
    }
    if (isError) {
        return <div className="text-red-500">Could not load events</div>;
    }
    if (safeEvents.length === 0) {
        return <div>No webhook events yet</div>;
    }

    return (
        <div className="space-y-4">
            <div className="flex items-center justify-between gap-3">
                <div className="flex items-center gap-2">
                    <h2 className="text-2xl font-bold">Recent webhook events</h2>
                    <Badge variant="outline">{safeEvents.length}</Badge>
                </div>
                <div className="flex items-center gap-2">
                    <span className="text-xs text-muted-foreground">Auto-sync enabled</span>
                    <Button variant="outline" size="sm" onClick={() => void refreshCommits()} disabled={isRefreshingCommits}>
                        {isRefreshingCommits ? "Refreshing..." : "Refresh commits"}
                    </Button>
                </div>
            </div>
            {syncSummary.length > 0 && (
                <div className="rounded-md border bg-muted/30 p-3 text-xs text-muted-foreground">
                    {syncSummary.map((entry) => (
                        <div key={entry}>{entry}</div>
                    ))}
                </div>
            )}
            {sortedEvents.map((event) => (
                <Card key={event.id} className="overflow-hidden w-full"> 
                    <CardHeader className="pb-2">
                        <div className="flex items-center justify-between w-full">
                            <div className="flex items-center gap-2">
                                <Badge variant="secondary">
                                    {event.event_type}
                                </Badge>
                                <span className="text-sm text-muted-foreground">
                                    {formatDistanceToNow(new Date(event.created), { addSuffix: true })}
                                </span>
                            </div>
                            <Button variant="ghost" size="sm" onClick={() => expandEventBehaviour(event.id)} className="h-8 w-8 p-0 shrink-0">
                                {expandedEventIds.includes(event.id) ? (
                                    <ChevronUp className="h-4 w-4" />
                                ) : (
                                    <ChevronDown className="h-4 w-4" />
                                )}
                            </Button>
                        </div>
                        <CardTitle className="text-base font-medium">
                            {event.repository}
                        </CardTitle>
                    </CardHeader>
                    <div className={getEventDetailsClassName(event.id)}>
                        <CardContent className="p-0 pt-6 pb-6">
                            {event.event_type === "commit" ? (
                                <CommitEventDetails payload={event.payload} repository={event.repository} />
                            ) : (
                                <pre className="text-xs bg-muted p-4 rounded overflow-auto">
                                    {JSON.stringify(event.payload, null, 2)}
                                </pre>
                            )}
                        </CardContent>
                    </div>
                </Card>
            ))}
        </div>
    );
}

function verifySignature(secret: string, payload: string, signatureHeader: string | null): boolean { // for incoming payloads including a x-hub-signature-256 header
    if (!signatureHeader) return false;
    const sig = signatureHeader.split('=')[1];
    if (!sig) return false;
    const hmac = createHmac('sha256', secret);
    const digest = hmac.update(payload).digest('hex');
    try {
        return timingSafeEqual(Buffer.from(sig), Buffer.from(digest));
    } catch {
        return false;
    }
}

export async function githubWebhook(request: HttpRequest, context: InvocationContext): Promise<HttpResponseInit> {
    try {
        context.log('GitHub webhook triggered');

        const signature = request.headers.get('x-hub-signature-256');
        if (!signature) {
            context.log('Missing signature x-hub-signature-256 header');
            return { status: 401, body: 'Unauthorized' };
        }

        let rawBody: string;
        let payload: any;
        try {
            rawBody = await request.text();
            payload = JSON.parse(rawBody); // parse the raw body
        } catch (err) {
            context.log('Failed to read/ parse body:', err);
            return { status: 400, body: 'Invalid body' };
        }

        const pocketbaseUrl = process.env.POCKETBASE_URL; // getting credentials from pocketbase, in order to obtain the webhookSecret field from the api_keys json
        const serviceToken = process.env.POCKETBASE_SERVICE_TOKEN;
        if (!pocketbaseUrl || !serviceToken) {
            context.log('Missing PocketBase configuration');
            return { status: 500, body: 'Server configuration error' };
        }

        const repoFullname = payload?.repository?.full_name;
        if (!repoFullname) {
            context.log('No repository info in payload');
            return { status: 400, body: 'Bad Request' };
        }
        const [owner, repo] = repoFullname.split('/');

        let credential: any;
        let memberId: string;
        let projectId: string;
        try {
            const filter = `(api_keys.owner='${owner}' && api_keys.repo='${repo}')`;
            const encodedFilter = encodeURIComponent(filter);
            const searchUrl = `${pocketbaseUrl}/api/collections/credentials/records?filter=${encodedFilter}&expand=member.project`;
            context.log('Search url:', searchUrl);
            
            const response = await fetch(searchUrl, {
                headers: {
                    Authorization: `Bearer ${serviceToken}`
                },
            });
            context.log(`PocketBase response status: ${response.status}`);
            const responseText = await response.text();
            if (!response.ok) {
                context.log(`PocketBase request failed: ${response.status} - ${responseText}`);
                return { status: 500, body: 'Failed to fetch credential from PocketBase' };
            }

            let data;
            try {
                data = JSON.parse(responseText);
            } catch (parseError) {
                context.log('Failed to parse PocketBase response as json:', parseError);
                return { status: 500, body: 'Invalid response from PocketBase' };
            }
            if (!data.items || data.items.length === 0) {
                context.log(`No credential found for repo ${repoFullname}`);
                return { status: 404, body: 'Not Found' };
            }

            credential = data.items[0];
            memberId = credential.member;
            projectId = credential.expand?.member?.expand?.project?.id;
            if (!projectId) {
                context.log('Could not determine project ID from credential');
                return { status: 500, body: 'Internal Server Error' };
            }
        } catch (err) {
            context.log('Failed to fetch credential from PocketBase', err);
            return { status: 500, body: 'Internal Server Error' };
        }

        const secret = credential.api_keys.webhookSecret;

        if (!verifySignature(secret, rawBody, signature)) { // since there are repo specific webhook secrets, the retrieved secret is verified for each repo included as credential for a project
            context.log('Invalid signature');
            return { status: 403, body: 'Forbidden' };
        }
        context.log('Signature verified');

        const backendUrl = process.env.BACKEND_BASE_URL;
        const backendToken = process.env.BACKEND_SERVICE_TOKEN;
        const event = request.headers.get('x-github-event');
        if (backendUrl && backendToken) {
            try {
                await fetch(`${backendUrl}/api/projects/${projectId}/members/${memberId}/webhook-events`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        Authorization: `Bearer ${backendToken}`,
                    },
                    body: JSON.stringify({
                        event,
                        repo: repoFullname,
                        data: payload,
                    }),
                });
            } catch (err) {
                context.log('error', 'Failed to forward event to backend:', err);
            }
        }

        return { status: 200, body: 'OK' };
    } catch (err) {
        context.error('Unhandled exception in githubWebhook:', err);
        return { status: 500, body: 'Internal Server Error' };
    }
}

export default async function KnowledgeGraphPage({ params }: KnowledgeGraphPageProps) {
    const { projectId } = await params;

    return (
        <div className="space-y-4">
            <KnowledgeGraphRootDirectory projectId={projectId} />
            <KnowledgeGraphCanvas projectId={projectId} />
        </div>
    );
}
